# MapperGPT — model definition
#
# Generated by AiMapper Model Studio.
# Architecture: decoder-only transformer (GPT-2 style, pre-LayerNorm, GELU MLP,
# tied input/output embeddings). Tensor names match the committed
# weights/model.safetensors manifest exactly.
from __future__ import annotations

import json
import math
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Optional

try:
    import torch
    import torch.nn as nn
    import torch.nn.functional as F
    HAS_TORCH = True
except ImportError:  # pragma: no cover - pure-structure mode
    HAS_TORCH = False
    torch = None
    nn = object


if HAS_TORCH:

    class CausalSelfAttention(nn.Module):
        def __init__(self, cfg: "ModelConfig"):
            super().__init__()
            self.n_head = cfg.n_head
            self.head_dim = cfg.d_model // cfg.n_head
            self.c_attn = nn.Linear(cfg.d_model, 3 * cfg.d_model)
            self.c_proj = nn.Linear(cfg.d_model, cfg.d_model)
            self.dropout = nn.Dropout(cfg.dropout)
            mask = torch.tril(torch.ones(cfg.n_ctx, cfg.n_ctx, dtype=torch.bool))
            self.register_buffer("causal_mask", mask.view(1, 1, cfg.n_ctx, cfg.n_ctx), persistent=False)

        def forward(self, x):
            B, T, C = x.shape
            q, k, v = self.c_attn(x).split(C, dim=2)
            q = q.view(B, T, self.n_head, self.head_dim).transpose(1, 2)
            k = k.view(B, T, self.n_head, self.head_dim).transpose(1, 2)
            v = v.view(B, T, self.n_head, self.head_dim).transpose(1, 2)
            att = (q @ k.transpose(-2, -1)) / math.sqrt(self.head_dim)
            att = att.masked_fill(~self.causal_mask[:, :, :T, :T], float("-inf"))
            att = F.softmax(att, dim=-1)
            att = self.dropout(att)
            y = (att @ v).transpose(1, 2).contiguous().view(B, T, C)
            return self.c_proj(y)

    class MLP(nn.Module):
        def __init__(self, cfg: "ModelConfig"):
            super().__init__()
            self.fc_in = nn.Linear(cfg.d_model, cfg.d_ff)
            self.fc_out = nn.Linear(cfg.d_ff, cfg.d_model)
            self.dropout = nn.Dropout(cfg.dropout)

        def forward(self, x):
            return self.dropout(self.fc_out(F.gelu(self.fc_in(x))))

    class Block(nn.Module):
        def __init__(self, cfg: "ModelConfig"):
            super().__init__()
            self.ln_1 = nn.LayerNorm(cfg.d_model)
            self.attn = CausalSelfAttention(cfg)
            self.ln_2 = nn.LayerNorm(cfg.d_model)
            self.mlp = MLP(cfg)

        def forward(self, x):
            x = x + self.attn(self.ln_1(x))
            x = x + self.mlp(self.ln_2(x))
            return x

    class GPT(nn.Module):
        """Inner transformer (produces hidden states)."""

        def __init__(self, cfg: "ModelConfig"):
            super().__init__()
            self.cfg = cfg
            self.tok_emb = nn.Embedding(cfg.vocab_size, cfg.d_model)
            self.pos_emb = nn.Embedding(cfg.n_ctx, cfg.d_model)
            self.blocks = nn.ModuleList([Block(cfg) for _ in range(cfg.n_layer)])
            self.ln_f = nn.LayerNorm(cfg.d_model)
            if cfg.tie_word_embeddings:
                self.lm_head = None
            self.apply(self._init_weights)

        def _init_weights(self, module):
            if isinstance(module, nn.Linear):
                nn.init.kaiming_normal_(module.weight, a=0, mode="fan_in", nonlinearity="relu")
                if self.cfg.scaled_init and module.out_features == self.cfg.d_model:
                    module.weight.data.mul_(1 / math.sqrt(2 * self.cfg.n_layer))
                if module.bias is not None:
                    nn.init.zeros_(module.bias)
            elif isinstance(module, nn.Embedding):
                nn.init.normal_(module.weight, mean=0.0, std=0.02)
            elif isinstance(module, nn.LayerNorm):
                nn.init.ones_(module.weight)
                nn.init.zeros_(module.bias)

        def forward(self, idx):
            B, T = idx.shape
            if T > self.cfg.n_ctx:
                raise ValueError(f"sequence length {T} exceeds context window {self.cfg.n_ctx}")
            pos = torch.arange(T, device=idx.device)
            x = self.tok_emb(idx) + self.pos_emb(pos)[None, :, :]
            for block in self.blocks:
                x = block(x)
            return self.ln_f(x)

    class MapperGPTForCausalLM(nn.Module):
        """Top-level model. State-dict keys match weights/model.safetensors."""

        def __init__(self, cfg: "ModelConfig"):
            super().__init__()
            self.cfg = cfg
            self.model = GPT(cfg)
            if cfg.tie_word_embeddings:
                self.lm_head = None
            else:
                self.lm_head = nn.Linear(cfg.d_model, cfg.vocab_size, bias=False)

        def forward(self, idx, targets: Optional["torch.Tensor"] = None):
            hidden = self.model(idx)
            if self.cfg.tie_word_embeddings:
                logits = hidden @ self.model.tok_emb.weight.t()
            else:
                logits = self.lm_head(hidden)
            loss = None
            if targets is not None:
                loss = F.cross_entropy(
                    logits.view(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1
                )
            return logits, loss

        def num_parameters(self, trainable_only: bool = True) -> int:
            params = self.parameters()
            if trainable_only:
                return sum(p.numel() for p in params if p.requires_grad)
            return sum(p.numel() for p in params)

        @torch.no_grad()
        def generate(self, idx, max_new_tokens=64, temperature=0.9, top_k=None):
            self.eval()
            for _ in range(max_new_tokens):
                idx_cond = idx[:, -self.cfg.n_ctx:]
                logits, _ = self(idx_cond)
                logits = logits[:, -1, :] / max(temperature, 1e-6)
                if top_k is not None:
                    v, _ = torch.topk(logits, min(top_k, logits.size(-1)))
                    logits[logits < v[:, [-1]]] = float("-inf")
                probs = F.softmax(logits, dim=-1)
                nxt = torch.multinomial(probs, num_samples=1)
                idx = torch.cat([idx, nxt], dim=1)
            return idx


@dataclass
class ModelConfig:
    vocab_size: int
    n_ctx: int
    d_model: int
    n_head: int
    d_ff: int
    n_layer: int
    tie_word_embeddings: bool = True
    dropout: float = 0.0
    scaled_init: bool = True
    model_type: str = "mapper_gpt"
    architectures: tuple = ("MapperGPTForCausalLM",)

    @property
    def head_dim(self) -> int:
        return self.d_model // self.n_head

    @classmethod
    def from_json(cls, path: str | Path) -> "ModelConfig":
        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        model_cfg = raw.get("model", raw)
        fields = {k: model_cfg[k] for k in (
            "vocab_size", "n_ctx", "d_model", "n_head", "d_ff", "n_layer"
        )}
        fields["tie_word_embeddings"] = bool(model_cfg.get("tie_word_embeddings", True))
        fields["dropout"] = float(model_cfg.get("dropout", 0.0))
        return cls(**fields)

    def to_dict(self) -> dict:
        data = asdict(self)
        data["architectures"] = list(self.architectures)
        return data

    def analytic_parameter_count(self) -> dict:
        """Independent closed-form count (must agree with the tensor manifest)."""
        d, V, ctx, ff, L = self.d_model, self.vocab_size, self.n_ctx, self.d_ff, self.n_layer
        embedding = V * d if self.tie_word_embeddings else 2 * V * d
        positional = ctx * d
        per_layer = 4 * d + (3 * d * d + 3 * d) + (d * d + d) + (ff * d + ff) + (d * ff + d)
        total = embedding + positional + per_layer * L + 2 * d
        return {
            "embedding": embedding,
            "positional": positional,
            "per_layer": per_layer,
            "blocks": per_layer * L,
            "final_ln": 2 * d,
            "total": total,
        }


def build_model(config_path: str | Path = "config.json") -> "MapperGPTForCausalLM":
    if not HAS_TORCH:
        raise RuntimeError("PyTorch is required to build the model: pip install torch")
    cfg = ModelConfig.from_json(config_path)
    return MapperGPTForCausalLM(cfg)


def load_pretrained(weights_path: str | Path = "weights/model.safetensors",
                    config_path: str | Path = "config.json") -> "MapperGPTForCausalLM":
    from safetensors.torch import load_file

    model = build_model(config_path)
    state = load_file(str(weights_path))
    missing, unexpected = model.load_state_dict(state, strict=False)
    # Tied models legitimately have no lm_head tensor.
    unexpected = [u for u in unexpected if not (model.cfg.tie_word_embeddings and u == "lm_head.weight")]
    if unexpected:
        raise RuntimeError(f"unexpected tensors in checkpoint: {unexpected}")
    if missing:
        raise RuntimeError(f"missing tensors in checkpoint: {missing}")
    model.eval()
    return model
